{"file_path": "frontend/src/services/api.ts", "initial_content": "import axios, { AxiosInstance } from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';

class ApiService {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: API_URL,
      headers: {
        'Content-Type': 'application/json',
      },
    });
  }

  // Upload document
  async uploadDocument(file: File): Promise<{
    success: boolean;
    document_id: string;
    filename: string;
    chunks: number;
    characters: number;
    message: string;
  }> {
    const formData = new FormData();
    formData.append('file', file);

    const response = await this.client.post('/api/upload', formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });

    return response.data;
  }

  // List documents
  async listDocuments(): Promise<Array<{
    document_id: string;
    filename: string;
    file_type: string;
    size: number;
  }>> {
    const response = await this.client.get('/api/documents');
    return response.data;
  }

  // Delete document
  async deleteDocument(documentId: string): Promise<{
    success: boolean;
    document_id: string;
    chunks_deleted: number;
    message: string;
  }> {
    const response = await this.client.delete(`/api/documents/${documentId}`);
    return response.data;
  }

  // Chat (non-streaming)
  async chat(question: string, documentId?: string, topK: number = 5): Promise<{
    answer: string;
    sources: Array<{
      filename: string;
      chunk_id: number;
      score: number;
      text: string;
    }>;
  }> {
    const response = await this.client.post('/api/chat', {
      question,
      document_id: documentId,
      top_k: topK,
      stream: false,
    });

    return response.data;
  }

  // Chat streaming
  async chatStream(
    question: string,
    onChunk: (chunk: string) => void,
    onSources: (sources: any[]) => void,
    onError: (error: Error) => void,
    onComplete: () => void,
    documentId?: string,
    topK: number = 5
  ): Promise<void> {
    try {
      const response = await fetch(`${API_URL}/api/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          question,
          document_id: documentId,
          top_k: topK,
          stream: true,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error('No response body');
      }

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6);

            if (data === '[DONE]') {
              onComplete();
              return;
            }

            try {
              const parsed = JSON.parse(data);
              if (parsed.type === 'sources') {
                onSources(parsed.data);
              } else if (parsed.type === 'answer') {
                onChunk(parsed.data);
              }
            } catch (e) {
              // Ignore parse errors
            }
          }
        }
      }

      onComplete();
    } catch (error) {
      onError(error as Error);
    }
  }

  // Health check
  async healthCheck(): Promise<{
    api: string;
    qdrant: string;
    ollama: string;
  }> {
    const response = await this.client.get('/health');
    return response.data;
  }
}

export default new ApiService();
"}

{"file_path": "frontend/src/App.tsx", "initial_content": "import React, { useState, useEffect } from 'react';
import FileUpload from './components/FileUpload';
import DocumentList from './components/DocumentList';
import ChatInterface from './components/ChatInterface';
import apiService from './services/api';

interface Document {
  document_id: string;
  filename: string;
  file_type: string;
  size: number;
}

function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDocument, setSelectedDocument] = useState<string | undefined>();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load documents on mount
  useEffect(() => {
    loadDocuments();
  }, []);

  const loadDocuments = async () => {
    try {
      setLoading(true);
      const docs = await apiService.listDocuments();
      setDocuments(docs);
      setError(null);
    } catch (err) {
      setError('Failed to load documents');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleUploadSuccess = () => {
    loadDocuments();
  };

  const handleDeleteDocument = async (documentId: string) => {
    try {
      await apiService.deleteDocument(documentId);
      if (selectedDocument === documentId) {
        setSelectedDocument(undefined);
      }
      loadDocuments();
    } catch (err) {
      setError('Failed to delete document');
      console.error(err);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {/* Header */}
      <header className="bg-white shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">
                🤖 AI Document QA System
              </h1>
              <p className="mt-1 text-sm text-gray-600">
                Upload documents and ask questions using RAG-powered AI
              </p>
            </div>
            <div className="flex items-center space-x-2 text-sm">
              <span className="inline-flex items-center px-3 py-1 rounded-full text-xs font-medium bg-green-100 text-green-800">
                <span className="w-2 h-2 mr-2 bg-green-500 rounded-full animate-pulse"></span>
                Online
              </span>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-red-800">{error}</p>
          </div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Sidebar - Upload & Documents */}
          <div className="lg:col-span-1 space-y-6">
            {/* Upload Section */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">
                📁 Upload Documents
              </h2>
              <FileUpload onUploadSuccess={handleUploadSuccess} />
            </div>

            {/* Documents List */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">
                📚 My Documents ({documents.length})
              </h2>
              <DocumentList
                documents={documents}
                selectedDocument={selectedDocument}
                onSelectDocument={setSelectedDocument}
                onDeleteDocument={handleDeleteDocument}
                loading={loading}
              />
            </div>
          </div>

          {/* Right Section - Chat Interface */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-lg shadow-md h-[calc(100vh-12rem)]">
              <div className="p-6 border-b border-gray-200">
                <h2 className="text-xl font-semibold text-gray-900">
                  💬 Ask Questions
                </h2>
                <p className="mt-1 text-sm text-gray-600">
                  {selectedDocument
                    ? `Asking about: ${documents.find(d => d.document_id === selectedDocument)?.filename}`
                    : 'Ask questions about all uploaded documents'}
                </p>
              </div>
              <ChatInterface
                documentId={selectedDocument}
                hasDocuments={documents.length > 0}
              />
            </div>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="mt-8 bg-white border-t border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <p className="text-center text-sm text-gray-500">
            Powered by Ollama + Qdrant + React | RAG-based Document QA System
          </p>
        </div>
      </footer>
    </div>
  );
}

export default App;
"}

{"file_path": "frontend/src/components/FileUpload.tsx", "initial_content": "import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import apiService from '../services/api';

interface FileUploadProps {
  onUploadSuccess: () => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onUploadSuccess }) => {
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState<string>('');
  const [error, setError] = useState<string | null>(null);

  const onDrop = useCallback(async (acceptedFiles: File[]) => {
    if (acceptedFiles.length === 0) return;

    const file = acceptedFiles[0];
    setUploading(true);
    setError(null);
    setProgress(`Uploading ${file.name}...`);

    try {
      const result = await apiService.uploadDocument(file);
      setProgress(`✓ ${result.message} (${result.chunks} chunks created)`);

      setTimeout(() => {
        setProgress('');
        onUploadSuccess();
      }, 2000);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to upload file');
      setProgress('');
    } finally {
      setUploading(false);
    }
  }, [onUploadSuccess]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    multiple: false,
    accept: {
      'application/pdf': ['.pdf'],
      'text/plain': ['.txt'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
      'application/msword': ['.doc'],
      'text/markdown': ['.md'],
      'text/csv': ['.csv'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'application/vnd.ms-excel': ['.xls'],
      'application/vnd.openxmlformats-officedocument.presentationml.presentation': ['.pptx'],
      'application/vnd.ms-powerpoint': ['.ppt'],
      'text/html': ['.html', '.htm'],
      'application/json': ['.json'],
    },
    disabled: uploading,
  });

  return (
    <div>
      <div
        {...getRootProps()}
        className={`
          border-2 border-dashed rounded-lg p-8 text-center cursor-pointer
          transition-all duration-200
          ${isDragActive ? 'border-blue-500 bg-blue-50' : 'border-gray-300 hover:border-blue-400'}
          ${uploading ? 'opacity-50 cursor-not-allowed' : ''}
        `}
      >
        <input {...getInputProps()} />

        <div className="space-y-2">
          <svg
            className="mx-auto h-12 w-12 text-gray-400"
            stroke="currentColor"
            fill="none"
            viewBox="0 0 48 48"
            aria-hidden="true"
          >
            <path
              d="M28 8H12a4 4 0 00-4 4v20m32-12v8m0 0v8a4 4 0 01-4 4H12a4 4 0 01-4-4v-4m32-4l-3.172-3.172a4 4 0 00-5.656 0L28 28M8 32l9.172-9.172a4 4 0 015.656 0L28 28m0 0l4 4m4-24h8m-4-4v8m-12 4h.02"
              strokeWidth={2}
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>

          {uploading ? (
            <p className="text-sm text-gray-600">Uploading...</p>
          ) : (
            <>
              <p className="text-sm text-gray-600">
                {isDragActive ? (
                  <span className="font-semibold text-blue-600">Drop file here</span>
                ) : (
                  <>
                    <span className="font-semibold text-blue-600">Click to upload</span> or drag and drop
                  </>
                )}
              </p>
              <p className="text-xs text-gray-500">
                PDF, DOCX, TXT, MD, CSV, XLSX, PPTX, HTML, JSON
              </p>
            </>
          )}
        </div>
      </div>

      {/* Progress */}
      {progress && (
        <div className="mt-3 p-3 bg-blue-50 border border-blue-200 rounded-lg">
          <p className="text-sm text-blue-800">{progress}</p>
        </div>
      )}

      {/* Error */}
      {error && (
        <div className="mt-3 p-3 bg-red-50 border border-red-200 rounded-lg">
          <p className="text-sm text-red-800">{error}</p>
        </div>
      )}

      {/* Supported formats info */}
      <div className="mt-4 text-xs text-gray-500">
        <p className="font-medium mb-1">Supported formats:</p>
        <div className="flex flex-wrap gap-1">
          {['PDF', 'DOCX', 'TXT', 'MD', 'CSV', 'XLSX', 'PPTX', 'HTML', 'JSON'].map(format => (
            <span key={format} className="px-2 py-1 bg-gray-100 rounded">
              {format}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
};

export default FileUpload;
"}

{"file_path": "frontend/src/components/DocumentList.tsx", "initial_content": "import React from 'react';

interface Document {
  document_id: string;
  filename: string;
  file_type: string;
  size: number;
}

interface DocumentListProps {
  documents: Document[];
  selectedDocument?: string;
  onSelectDocument: (documentId: string | undefined) => void;
  onDeleteDocument: (documentId: string) => void;
  loading: boolean;
}

const DocumentList: React.FC<DocumentListProps> = ({
  documents,
  selectedDocument,
  onSelectDocument,
  onDeleteDocument,
  loading,
}) => {
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
  };

  const getFileIcon = (fileType: string): string => {
    const type = fileType.toLowerCase();
    if (type.includes('pdf')) return '📄';
    if (type.includes('doc')) return '📝';
    if (type.includes('xls') || type.includes('csv')) return '📊';
    if (type.includes('ppt')) return '📑';
    if (type.includes('txt') || type.includes('md')) return '📃';
    if (type.includes('html')) return '🌐';
    if (type.includes('json')) return '🔧';
    return '📁';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="animate-pulse text-gray-400">Loading...</div>
      </div>
    );
  }

  if (documents.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        <p className="text-sm">No documents uploaded yet</p>
        <p className="text-xs mt-1">Upload a document to get started</p>
      </div>
    );
  }

  return (
    <div className="space-y-2 max-h-96 overflow-y-auto">
      {/* All Documents Option */}
      <button
        onClick={() => onSelectDocument(undefined)}
        className={`
          w-full text-left p-3 rounded-lg transition-all
          ${!selectedDocument
            ? 'bg-blue-50 border-2 border-blue-500'
            : 'bg-gray-50 border-2 border-transparent hover:border-gray-300'
          }
        `}
      >
        <div className="flex items-center">
          <span className="text-2xl mr-3">📚</span>
          <div className="flex-1">
            <p className="font-medium text-sm text-gray-900">All Documents</p>
            <p className="text-xs text-gray-500">Search across all files</p>
          </div>
        </div>
      </button>

      {/* Individual Documents */}
      {documents.map((doc) => (
        <div
          key={doc.document_id}
          className={`
            p-3 rounded-lg border-2 transition-all
            ${selectedDocument === doc.document_id
              ? 'bg-blue-50 border-blue-500'
              : 'bg-gray-50 border-transparent hover:border-gray-300'
            }
          `}
        >
          <div className="flex items-start">
            <button
              onClick={() => onSelectDocument(doc.document_id)}
              className="flex-1 text-left flex items-start"
            >
              <span className="text-2xl mr-3">{getFileIcon(doc.file_type)}</span>
              <div className="flex-1 min-w-0">
                <p className="font-medium text-sm text-gray-900 truncate">
                  {doc.filename}
                </p>
                <p className="text-xs text-gray-500 mt-1">
                  {doc.file_type} • {formatFileSize(doc.size)}
                </p>
              </div>
            </button>

            <button
              onClick={(e) => {
                e.stopPropagation();
                if (window.confirm(`Delete ${doc.filename}?`)) {
                  onDeleteDocument(doc.document_id);
                }
              }}
              className="ml-2 p-1 text-red-500 hover:bg-red-50 rounded transition-colors"
              title="Delete document"
            >
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                />
              </svg>
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default DocumentList;
"}

{"file_path": "frontend/src/components/ChatInterface.tsx", "initial_content": "import React, { useState, useRef, useEffect } from 'react';
import MessageBubble from './MessageBubble';
import apiService from '../services/api';

interface Message {
  id: string;
  type: 'user' | 'assistant';
  content: string;
  sources?: any[];
  timestamp: Date;
}

interface ChatInterfaceProps {
  documentId?: string;
  hasDocuments: boolean;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ documentId, hasDocuments }) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      type: 'user',
      content: input,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    // Create placeholder for assistant message
    const assistantMessageId = (Date.now() + 1).toString();
    const assistantMessage: Message = {
      id: assistantMessageId,
      type: 'assistant',
      content: '',
      sources: [],
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      let fullAnswer = '';
      let sources: any[] = [];

      await apiService.chatStream(
        input,
        (chunk) => {
          fullAnswer += chunk;
          setMessages(prev =>
            prev.map(msg =>
              msg.id === assistantMessageId
                ? { ...msg, content: fullAnswer }
                : msg
            )
          );
        },
        (receivedSources) => {
          sources = receivedSources;
          setMessages(prev =>
            prev.map(msg =>
              msg.id === assistantMessageId
                ? { ...msg, sources: receivedSources }
                : msg
            )
          );
        },
        (error) => {
          console.error('Streaming error:', error);
          setMessages(prev =>
            prev.map(msg =>
              msg.id === assistantMessageId
                ? { ...msg, content: 'Error: Failed to get response. Please try again.' }
                : msg
            )
          );
        },
        () => {
          setIsLoading(false);
        },
        documentId
      );
    } catch (error) {
      console.error('Error:', error);
      setMessages(prev =>
        prev.map(msg =>
          msg.id === assistantMessageId
            ? { ...msg, content: 'Error: Failed to get response. Please try again.' }
            : msg
        )
      );
      setIsLoading(false);
    }
  };

  const clearChat = () => {
    setMessages([]);
  };

  return (
    <div className="flex flex-col h-[calc(100%-5rem)]">
      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-4">
        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center">
            <div className="text-6xl mb-4">💬</div>
            <h3 className="text-xl font-semibold text-gray-700 mb-2">
              Start a conversation
            </h3>
            <p className="text-gray-500 max-w-md">
              {hasDocuments
                ? 'Ask any question about your uploaded documents. The AI will use RAG to find relevant information and provide accurate answers.'
                : 'Upload some documents first to start asking questions!'}
            </p>
            {hasDocuments && (
              <div className="mt-6 text-left">
                <p className="text-sm font-medium text-gray-700 mb-2">Example questions:</p>
                <ul className="text-sm text-gray-600 space-y-1">
                  <li>• "What is the main topic of this document?"</li>
                  <li>• "Summarize the key points"</li>
                  <li>• "What does it say about [specific topic]?"</li>
                </ul>
              </div>
            )}
          </div>
        ) : (
          <>
            {messages.map((message) => (
              <MessageBubble key={message.id} message={message} />
            ))}
            <div ref={messagesEndRef} />
          </>
        )}
      </div>

      {/* Input Area */}
      <div className="border-t border-gray-200 p-4 bg-gray-50">
        {messages.length > 0 && (
          <button
            onClick={clearChat}
            className="mb-2 text-xs text-gray-500 hover:text-gray-700 transition-colors"
          >
            Clear conversation
          </button>
        )}

        <form onSubmit={handleSubmit} className="flex space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder={hasDocuments ? "Ask a question about your documents..." : "Upload documents first..."}
            disabled={!hasDocuments || isLoading}
            className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-100 disabled:cursor-not-allowed"
          />
          <button
            type="submit"
            disabled={!hasDocuments || !input.trim() || isLoading}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors font-medium"
          >
            {isLoading ? (
              <span className="flex items-center">
                <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Thinking...
              </span>
            ) : (
              'Send'
            )}
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatInterface;
"}

